// Entire CLI extension for Pi
// Auto-generated by `entire enable --agent pi`
// Do not edit manually — changes will be overwritten on next install.
//
// Forwards Pi lifecycle events to `entire hooks pi <event>` so Entire can
// create checkpoints, capture transcripts, and offer rewind/resume.
//
// ENTIRE_CMD is replaced at install time by Entire's installer.

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { execFile } from "node:child_process";

export default function (pi: ExtensionAPI) {
  // A Pi subagent is a nested `pi` process: subagent extensions spawn one per
  // task (`pi --mode json -p --no-session`) with cwd inside the project, where Pi
  // auto-discovers project-local `.pi/extensions/*/index.ts` — this file. Without
  // a guard the child forwards its own lifecycle as if it were the user's session,
  // claiming the parent's session (a sessionless child) or opening a second one.
  // Mark this process so any Pi it spawns can tell that it is nested.
  //
  // Only this extension reads the marker. Entire's hook subprocesses inherit it
  // too, so the CLI side must NOT treat it as a skip signal.
  if (process.env.ENTIRE_PI_NESTED === "1") return;
  process.env.ENTIRE_PI_NESTED = "1";

  const ENTIRE_CMD = '__ENTIRE_CMD__';
  let pendingSkillEvents: Array<{ skill_name: string; invocation: string; timestamp: string }> = [];

  // fireHook pipes data to `entire hooks pi <hookName>` and resolves with the
  // hook's stdout (empty string on any failure). Most hooks ignore the return;
  // before_agent_start uses it to apply a model-context injection.
  function fireHook(hookName: string, data: Record<string, unknown>): Promise<string> {
    return new Promise((resolve) => {
      try {
        const child = execFile(
          "sh",
          ["-c", `${ENTIRE_CMD} hooks pi ${hookName}`],
          { timeout: 10000, windowsHide: true, maxBuffer: 4 * 1024 * 1024 },
          (_err, stdout) => resolve(typeof stdout === "string" ? stdout : ""),
        );
        child.stdin?.end(JSON.stringify(data));
      } catch {
        // best effort — never block the agent on a hook failure
        resolve("");
      }
    });
  }

  // parseInjectedContext scans a hook's stdout for Entire's injection envelope
  // ({"inject_context":"..."}) and returns the text to inject, or null.
  function parseInjectedContext(stdout: string): string | null {
    if (!stdout) return null;
    for (const line of stdout.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed.startsWith("{")) continue;
      try {
        const parsed = JSON.parse(trimmed) as { inject_context?: unknown };
        if (typeof parsed.inject_context === "string" && parsed.inject_context.length > 0) {
          return parsed.inject_context;
        }

